for path, pairs in EDITS.items():
    file = root / path
    text = file.read_text()
    for old, new, count in pairs:
        found = text.count(old)
        assert found == count, f"{path}: {found} matches of {old[:80]!r}, expected {count}"
        text = text.replace(old, new)
    file.write_text(text)
    print(f"{path}: {len(pairs)} edits, each match counted")

DELETES = "[\"spec/api/HttpSurface/refused/FormOfContainer.CS1503.cs.txt\",\"spec/api/HttpSurface/refused/FormWithNoForm.CS1501.cs.txt\",\"spec/api/HttpSurface/refused/FormInJson.CS1929.cs.txt\",\"spec/api/HttpSurface/refused/PageFormGone.CS0411.cs.txt\"]"

for path in json.loads(DELETES):
    file = root / path
    assert file.exists(), f"{path}: not found"
    file.unlink()
    print(f"{path}: deleted")

for path, text in CREATES.items():
    (root / path).write_text(text)
    print(f"{path}: written")

plants_file = root / "spec/plants/tlc.json"
