assert json.dumps(plants, indent=1, ensure_ascii=False) + "\n" == plants_text, "spec/plants/tlc.json is not in the form this script writes"
names = {plant["name"] for plant in plants}
assert not names & {plant["name"] for plant in PLANTS}, "a plant of this unit is already in spec/plants/tlc.json"
plants_file.write_text(json.dumps(plants + PLANTS, indent=1, ensure_ascii=False) + "\n")
print(f"spec/plants/tlc.json: {len(PLANTS)} plants added")
